"""The ledger: validated transactions and exact balances."""
import re

from tallybook.accounts import Chart, parent_path
from tallybook.currency import RateTable, is_date
from tallybook.dates import format_date
from tallybook.errors import NotFoundError, ValidationError
from tallybook.money import Money, format_minor
from tallybook.model import Posting, Transaction

_TAG = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


class LedgerError(ValidationError):
    pass


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _one_line(value):
    return isinstance(value, str) and "\n" not in value and "\r" not in value


class Ledger:
    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._max_id = 0

    def __len__(self):
        return len(self._txs)

    # -- validation -----------------------------------------------------
    def _prepare(self, tx, ids_in_use):
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: %r" % (tx,))
        if not is_date(tx.date):
            raise LedgerError("transaction date must be a date, not %r" % (tx.date,))
        if tx.flag not in ("*", "!") or not isinstance(tx.flag, str):
            raise LedgerError("invalid flag %r: use * or !" % (tx.flag,))
        if not _one_line(tx.payee):
            raise LedgerError("payee must be text without a line break")
        if not _one_line(tx.narration):
            raise LedgerError("narration must be text without a line break")
        if not isinstance(tx.tags, (list, tuple, set, frozenset)):
            raise LedgerError("tags must be a list of names")
        for tag in tx.tags:
            if not isinstance(tag, str) or not _TAG.fullmatch(tag):
                raise LedgerError("invalid tag %r" % (tag,))
        if not isinstance(tx.postings, (list, tuple)):
            raise LedgerError("postings must be a list")
        postings = list(tx.postings)
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        for p in postings:
            if not isinstance(p, Posting):
                raise LedgerError("not a posting: %r" % (p,))
            if not _one_line(p.note):
                raise LedgerError("a posting note must be text without a line break")
            if p.amount is not None and not isinstance(p.amount, Money):
                raise LedgerError("a posting amount must be money or None")
        for p in postings:
            if not self.chart.exists(p.account):
                raise LedgerError("unknown account %s" % (p.account,))
            if not self.chart.is_open(p.account, tx.date):
                raise LedgerError("account %s is not open on %s" % (p.account, format_date(tx.date)))
            self._check_currency(p.account, p.amount)
        missing = [i for i, p in enumerate(postings) if p.amount is None]
        if len(missing) > 1:
            raise LedgerError("more than one posting without an amount")
        sums = {}
        for p in postings:
            if p.amount is not None:
                sums[p.amount.currency] = sums.get(p.amount.currency, 0) + p.amount.minor
        off = sorted(c for c, v in sums.items() if v != 0)
        if missing:
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            i = missing[0]
            gap = postings[i]
            filled = []
            for cur in off:
                amount = Money(-sums[cur], cur)
                self._check_currency(gap.account, amount)
                filled.append(Posting(gap.account, amount, gap.note))
            postings[i:i + 1] = filled
        elif off:
            raise LedgerError("transaction does not balance: " + ", ".join(
                "%s %s" % (c, format_minor(sums[c], c)) for c in off))
        if tx.id is None:
            new_id = self._max_id + 1
        else:
            if not _is_int(tx.id) or tx.id < 1:
                raise LedgerError("invalid transaction id %r" % (tx.id,))
            if tx.id in ids_in_use:
                raise LedgerError("transaction id %d already exists" % tx.id)
            new_id = tx.id
        return Transaction(tx.date, tx.payee, tx.narration, postings,
                           tuple(sorted(set(tx.tags))), tx.flag, new_id)

    def _check_currency(self, account, amount):
        if amount is None:
            return
        held = self.chart.get(account).currency
        if held is not None and held != amount.currency:
            raise LedgerError("account %s only holds %s, not %s" % (account, held, amount.currency))

    def _store(self, stored):
        self._txs[stored.id] = stored
        if stored.id > self._max_id:
            self._max_id = stored.id

    # -- changing ---------------------------------------------------------
    def add(self, tx):
        stored = self._prepare(tx, self._txs)
        self._store(stored)
        return stored

    def add_many(self, transactions):
        snapshot = (dict(self._txs), self._max_id)
        out = []
        try:
            for tx in transactions:
                out.append(self.add(tx))
        except BaseException:
            self._txs, self._max_id = snapshot
            raise
        return out

    def replace(self, id, tx):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: %r" % (tx,))
        if tx.id is not None and tx.id != id:
            raise LedgerError("transaction id %s does not match %s" % (tx.id, id))
        probe = Transaction(tx.date, tx.payee, tx.narration, tx.postings, tx.tags, tx.flag, None)
        stored = self._prepare(probe, self._txs)
        stored.id = id
        self._txs[id] = stored
        return stored

    def remove(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return self._txs.pop(id)

    # -- reading ------------------------------------------------------------
    def get(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return self._txs[id]

    def transactions(self):
        return sorted(self._txs.values(), key=lambda t: (t.date, t.id))

    def postings(self):
        for tx in self.transactions():
            for p in tx.postings:
                yield tx, p

    def _sums(self, as_of, rollup):
        if as_of is not None and not is_date(as_of):
            raise LedgerError("as_of must be a date, not %r" % (as_of,))
        out = {}
        for tx, p in self.postings():
            if as_of is not None and tx.date > as_of:
                continue
            if p.amount is None:
                continue
            path = p.account
            while path is not None:
                cur = out.setdefault(path, {})
                cur[p.amount.currency] = cur.get(p.amount.currency, 0) + p.amount.minor
                path = parent_path(path) if rollup else None
        return out

    def _clean(self, sums):
        out = {}
        for account, cur in sums.items():
            kept = {c: v for c, v in cur.items() if v != 0}
            if kept:
                out[account] = kept
        return out

    def balances(self, as_of=None):
        return self._clean(self._sums(as_of, False))

    def rollup_balances(self, as_of=None):
        return self._clean(self._sums(as_of, True))

    def balance(self, account, as_of=None, currency=None, rollup=True):
        if not self.chart.exists(account):
            raise NotFoundError("no such account: %s" % (account,))
        table = self.rollup_balances(as_of) if rollup else self.balances(as_of)
        mine = table.get(account, {})
        if currency is not None:
            return Money(mine.get(currency, 0), currency)
        return {c: Money(v, c) for c, v in mine.items()}
"""The chart of accounts."""
import re

from tallybook.currency import CURRENCIES, is_date
from tallybook.dates import format_date
from tallybook.errors import NotFoundError, ValidationError
from tallybook.model import Account

ROOTS = {
    "Assets": "asset",
    "Liabilities": "liability",
    "Equity": "equity",
    "Income": "income",
    "Expenses": "expense",
}
TYPES = tuple(ROOTS.values())

_SEGMENT = re.compile(r"[A-Z][A-Za-z0-9_-]*")


class ChartError(ValidationError):
    def __init__(self, message="", code=None, detail=None):
        ValidationError.__init__(self, message, detail)
        if code is not None:
            self.code = code


def valid_path(text):
    if not isinstance(text, str):
        return False
    parts = text.split(":")
    if parts[0] not in ROOTS:
        return False
    return all(_SEGMENT.fullmatch(p) for p in parts[1:])


def _need_valid(path):
    if not valid_path(path):
        raise ChartError("invalid account path '%s'" % (path,))


def parent_path(path):
    _need_valid(path)
    head, sep, _ = path.rpartition(":")
    return head if sep else None


def account_type(path):
    _need_valid(path)
    return ROOTS[path.split(":")[0]]


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ChartError("invalid account pattern '%s'" % (pattern,))
    parts = pattern.split(":")
    for p in parts:
        if p not in ("*", "**") and not _SEGMENT.fullmatch(p):
            raise ChartError("invalid account pattern '%s'" % pattern)
    return parts


def _match_parts(pat, seg):
    # pat: pattern segments; seg: path segments; ** = one or more segments
    if not pat:
        return not seg
    head = pat[0]
    if head == "**":
        for k in range(1, len(seg) + 1):
            if _match_parts(pat[1:], seg[k:]):
                return True
        return False
    if not seg:
        return False
    if head != "*" and head != seg[0]:
        return False
    return _match_parts(pat[1:], seg[1:])


def path_matches(pattern, path):
    parts = _check_pattern(pattern)
    if not isinstance(path, str):
        return False
    if "*" not in pattern:
        return path == pattern or path.startswith(pattern + ":")
    return _match_parts(parts, path.split(":"))


def _sort_key(account):
    return account.path.split(":")


class Chart:
    def __init__(self):
        self._accounts = {}
        self._implicit = set()

    def __contains__(self, path):
        return self.exists(path)

    def exists(self, path):
        return isinstance(path, str) and path in self._accounts

    def __len__(self):
        return len(self._accounts)

    def add(self, path, type=None, currency=None, opened=None, note=""):
        _need_valid(path)
        kind = ROOTS[path.split(":")[0]]
        if type is not None and (type not in TYPES or type != kind):
            raise ChartError("type '%s' does not fit account %s (a %s)" % (type, path, kind))
        if currency is not None and (not isinstance(currency, str) or currency not in CURRENCIES):
            raise ChartError("unknown currency '%s'" % (currency,))
        if opened is not None and not is_date(opened):
            raise ChartError("opened must be a date, not %r" % (opened,))
        if not isinstance(note, str):
            raise ChartError("note must be text")
        if path in self._accounts and path not in self._implicit:
            raise ChartError("account %s already exists" % path, code="conflict")
        if path in self._accounts:
            acc = self._accounts[path]
            acc.currency, acc.opened, acc.note = currency, opened, note
            self._implicit.discard(path)
            return acc
        parents = []
        parent = parent_path(path)
        while parent is not None and parent not in self._accounts:
            parents.append(parent)
            parent = parent_path(parent)
        for p in parents:
            self._accounts[p] = Account(p, ROOTS[p.split(":")[0]])
            self._implicit.add(p)
        acc = Account(path, kind, currency, opened, None, note)
        self._accounts[path] = acc
        return acc

    def get(self, path):
        if not self.exists(path):
            raise NotFoundError("no such account: %s" % (path,))
        return self._accounts[path]

    def accounts(self):
        return sorted(self._accounts.values(), key=_sort_key)

    def children(self, path):
        self.get(path)
        n = len(path.split(":")) + 1
        return [a for a in self.descendants(path) if len(a.path.split(":")) == n]

    def descendants(self, path):
        self.get(path)
        prefix = path + ":"
        return [a for a in self.accounts() if a.path.startswith(prefix)]

    def is_leaf(self, path):
        return not self.children(path)

    def is_open(self, path, on):
        acc = self.get(path)
        if not is_date(on):
            raise ChartError("not a date: %r" % (on,))
        return (acc.opened is None or acc.opened <= on) and (acc.closed is None or on <= acc.closed)

    def close(self, path, on):
        acc = self.get(path)
        if not is_date(on):
            raise ChartError("not a date: %r" % (on,))
        if acc.closed is not None:
            raise ChartError("account %s is already closed" % path)
        if acc.opened is not None and on < acc.opened:
            raise ChartError("cannot close %s on %s: it opened on %s"
                             % (path, format_date(on), format_date(acc.opened)))
        acc.closed = on
        return acc

    def matches(self, pattern):
        _check_pattern(pattern)
        return [a for a in self.accounts() if path_matches(pattern, a.path)]

