"""The journal file: a whole book as readable text."""
import re
from dataclasses import dataclass, field
from datetime import date
from typing import List, Tuple

from tallybook.accounts import account_type, valid_path
from tallybook.currency import CURRENCIES
from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import ParseError
from tallybook.ledger import Ledger
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money, parse_amount

_BLANKS = " \t"
_TAG = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_RATE = re.compile(r"([0-9]+)(?:\.([0-9]{1,8}))?")


class JournalError(ParseError):
    def __init__(self, message="", line=None, detail=None):
        ParseError.__init__(self, message, detail)
        self.line = line


class _Bad(Exception):
    """A mistake inside one line (the line number is added by the caller)."""


@dataclass
class Journal:
    accounts: List[Account] = field(default_factory=list)
    rates: List[Tuple] = field(default_factory=list)
    transactions: List[Transaction] = field(default_factory=list)

    def to_ledger(self):
        ledger = Ledger()
        for acc in self.accounts:
            ledger.chart.add(acc.path, type=acc.type, currency=acc.currency,
                             opened=acc.opened, note=acc.note)
            if acc.closed is not None:
                ledger.chart.close(acc.path, acc.closed)
        for src, dst, on, text in self.rates:
            ledger.rates.set(src, dst, text, on)
        for tx in self.transactions:
            ledger.add(tx)
        return ledger


# -- reading -------------------------------------------------------------

def _scan(line):
    """Split a line into tokens and a trailing comment.

    Returns ``(tokens, comment)``; a token is ``("w", word)`` or ``("q", text)``.
    ``comment`` is the text after the first ``;`` outside quotes, or None.
    """
    tokens = []
    n = len(line)
    i = 0
    while i < n:
        c = line[i]
        if c in _BLANKS:
            i += 1
        elif c == ";":
            return tokens, line[i + 1:]
        elif c == '"':
            out = []
            i += 1
            while True:
                if i >= n:
                    raise _Bad("missing closing quote")
                c = line[i]
                if c == '"':
                    i += 1
                    break
                if c == "\\":
                    if i + 1 < n and line[i + 1] in '"\\':
                        out.append(line[i + 1])
                        i += 2
                        continue
                    raise _Bad("bad backslash in quoted text (use \\\\ or \\\")")
                out.append(c)
                i += 1
            if i < n and line[i] not in _BLANKS and line[i] != ";":
                raise _Bad("text right after a closing quote")
            tokens.append(("q", "".join(out)))
        else:
            j = i
            while j < n and line[j] not in _BLANKS and line[j] != ";":
                j += 1
            tokens.append(("w", line[i:j]))
            i = j
    return tokens, None


def _date(text):
    try:
        return parse_date(text)
    except DateError:
        raise _Bad("invalid date '%s'" % text)


def _currency(code):
    if code not in CURRENCIES:
        raise _Bad("unknown currency '%s'" % code)
    return code


def _word(tokens, i, what):
    if i >= len(tokens) or tokens[i][0] != "w":
        raise _Bad("expected %s" % what)
    return tokens[i][1]


def _parse_account(tokens):
    path = _word(tokens, 1, "an account path")
    if not valid_path(path):
        raise _Bad("invalid account path '%s'" % path)
    cur = opened = closed = None
    note = ""
    i = 2
    n = len(tokens)
    if i < n and tokens[i][0] == "w" and tokens[i][1] not in ("open", "close"):
        cur = _currency(tokens[i][1])
        i += 1
    if i < n and tokens[i] == ("w", "open"):
        opened = _date(_word(tokens, i + 1, "a date after open"))
        i += 2
    if i < n and tokens[i] == ("w", "close"):
        closed = _date(_word(tokens, i + 1, "a date after close"))
        i += 2
    if i < n and tokens[i][0] == "q":
        note = tokens[i][1]
        i += 1
    if i < n:
        raise _Bad("unexpected '%s' in account line" % tokens[i][1])
    if opened is not None and closed is not None and closed < opened:
        raise _Bad("account closes before it opens")
    return Account(path, account_type(path), cur, opened, closed, note)


def _parse_rate(tokens):
    if len(tokens) != 5 or any(k != "w" for k, _ in tokens):
        raise _Bad("a rate line is: rate DATE FROM TO RATE")
    on = _date(tokens[1][1])
    src = _currency(tokens[2][1])
    dst = _currency(tokens[3][1])
    if src == dst:
        raise _Bad("a rate needs two different currencies")
    text = tokens[4][1]
    m = _RATE.fullmatch(text)
    if m is None:
        raise _Bad("invalid rate '%s'" % text)
    if not (m.group(1).strip("0") or (m.group(2) or "").strip("0")):
        raise _Bad("a rate must be positive, not '%s'" % text)
    return (src, dst, on, text)


def _parse_tx_line(tokens):
    on = _date(tokens[0][1]) if tokens[0][0] == "w" else None
    if on is None:
        raise _Bad("a line must start with a date, account or rate")
    i = 1
    flag = "*"
    if i < len(tokens) and tokens[i][0] == "w" and tokens[i][1] in ("*", "!"):
        flag = tokens[i][1]
        i += 1
    strings = []
    while i < len(tokens) and tokens[i][0] == "q":
        strings.append(tokens[i][1])
        i += 1
    if not strings:
        raise _Bad("a transaction needs a quoted payee")
    if len(strings) > 2:
        raise _Bad("a transaction has at most a payee and a narration")
    tags = set()
    while i < len(tokens):
        kind, value = tokens[i]
        if kind != "w" or not value.startswith("#") or not _TAG.fullmatch(value[1:]):
            raise _Bad("unexpected '%s' in transaction line" % value)
        tags.add(value[1:])
        i += 1
    narration = strings[1] if len(strings) == 2 else ""
    return Transaction(on, strings[0], narration, [], tuple(sorted(tags)), flag, None)


def _parse_posting(tokens, comment):
    if any(k != "w" for k, _ in tokens):
        raise _Bad("quoted text is not allowed in a posting")
    path = tokens[0][1]
    if not valid_path(path):
        raise _Bad("invalid account path '%s'" % path)
    note = comment.strip(_BLANKS) if comment is not None else ""
    if len(tokens) == 1:
        return Posting(path, None, note)
    if len(tokens) != 3:
        raise _Bad("a posting is: ACCOUNT or ACCOUNT AMOUNT CURRENCY")
    cur = _currency(tokens[2][1])
    try:
        minor = parse_amount(tokens[1][1], cur)
        amount = Money(minor, cur)
    except (ParseError, ValueError, OverflowError) as err:
        raise _Bad(str(err))
    except Exception as err:  # MoneyError and friends are ValidationErrors
        if hasattr(err, "message"):
            raise _Bad(err.message)
        raise
    return Posting(path, amount, note)


def parse_journal(text):
    if not isinstance(text, str):
        raise JournalError("journal text must be a string")
    if text.startswith("﻿"):
        text = text[1:]
    journal = Journal()
    seen = set()
    current = None
    for number, raw in enumerate(text.split("\n"), 1):
        line = raw[:-1] if raw.endswith("\r") else raw
        stripped = line.strip(_BLANKS)
        if stripped == "":
            current = None
            continue
        if stripped[0] in ";#":
            continue
        try:
            tokens, comment = _scan(line)
            if line[0] in _BLANKS:
                if current is None:
                    raise _Bad("indented line outside a transaction")
                current.postings.append(_parse_posting(tokens, comment))
                continue
            current = None
            head = tokens[0] if tokens else None
            if head == ("w", "account"):
                acc = _parse_account(tokens)
                if acc.path in seen:
                    raise _Bad("account %s is declared twice" % acc.path)
                seen.add(acc.path)
                journal.accounts.append(acc)
            elif head == ("w", "rate"):
                journal.rates.append(_parse_rate(tokens))
            else:
                current = _parse_tx_line(tokens)
                journal.transactions.append(current)
        except _Bad as err:
            raise JournalError("line %d: %s" % (number, err), number)
    return journal


# -- writing -------------------------------------------------------------

def _quote(text):
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _account_line(acc):
    parts = ["account " + acc.path]
    if acc.currency:
        parts.append(acc.currency)
    if acc.opened is not None:
        parts.append("open " + format_date(acc.opened))
    if acc.closed is not None:
        parts.append("close " + format_date(acc.closed))
    if acc.note:
        parts.append(_quote(acc.note))
    return " ".join(parts)


def format_transaction(tx):
    head = "%s %s %s" % (format_date(tx.date), tx.flag, _quote(tx.payee))
    if tx.narration:
        head += " " + _quote(tx.narration)
    for tag in sorted(set(tx.tags)):
        head += " #" + tag
    lines = [head]
    with_amount = [p for p in tx.postings if p.amount is not None]
    name_width = max([len(p.account) for p in with_amount] or [0])
    amount_width = max([len(p.amount.amount_str()) for p in with_amount] or [0])
    for p in tx.postings:
        if p.amount is None:
            row = "  " + p.account
        else:
            row = "  %s  %s %s" % (p.account.ljust(name_width),
                                   p.amount.amount_str().rjust(amount_width), p.amount.currency)
        if p.note:
            row += "  ; " + p.note
        lines.append(row)
    return "\n".join(lines) + "\n"


def format_journal(journal):
    blocks = []
    if journal.accounts:
        blocks.append("".join(_account_line(a) + "\n" for a in journal.accounts))
    if journal.rates:
        blocks.append("".join("rate %s %s %s %s\n" % (format_date(on), src, dst, text)
                              for src, dst, on, text in journal.rates))
    blocks.extend(format_transaction(tx) for tx in journal.transactions)
    return "\n".join(blocks)

