    ``comment`` is the text after the first ``;`` outside quotes, or None.
    """
    tokens = []
    n = len(line)
    i = 0
    while i < n:
        c = line[i]
        if c in _BLANKS:
            i += 1
        elif c == ";":
            return tokens, line[i + 1:]
        elif c == '"':
            out = []
            i += 1
            while True:
                if i >= n:
                    raise _Bad("missing closing quote")
                c = line[i]
                if c == '"':
                    i += 1
                    break
                if c == "\\":
                    if i + 1 < n and line[i + 1] in '"\\':
                        out.append(line[i + 1])
                        i += 2
                        continue
                    raise _Bad("bad backslash in quoted text (use \\\\ or \\\")")
                out.append(c)
