        stack = []
        for op, arg in self._program:
            if op == "t":
                stack.append(arg(tx, posting))
            elif op == "not":
                stack.append(not stack.pop())
            elif op == "and":
                b = stack.pop()
                stack.append(stack.pop() and b)
            else:
                b = stack.pop()
                stack.append(stack.pop() or b)
        return stack[-1]

    def matching_postings(self, tx):
        if not self._program:
            return list(tx.postings)
        return [p for p in tx.postings if self._holds(tx, p)]

    def matches(self, tx):
        if not self._program:
            return True
        return any(self._holds(tx, p) for p in tx.postings)


def select(transactions, q):
    if isinstance(q, str):
        q = parse_query(q)
    return [tx for tx in transactions if q.matches(tx)]


# -- term builders ------------------------------------------------------------

def _contains_text(text):
    needle = text.lower()
    return lambda tx, p: needle in tx.payee.lower() or needle in tx.narration.lower()


def _compare_term(value, op, kind):
    cmp = _OPFUNC[op]
    if kind == "date":
        return lambda tx, p: cmp(tx.date, value)
    return lambda tx, p: compare_amount(p.amount, value, op)


def _named_term(name, value, chart, start):
    """Build the predicate for ``name:value`` or raise QueryError at ``start``."""
    if name == "payee":
        needle = value.lower()
        return lambda tx, p: needle in tx.payee.lower()
    if name == "narration":
        needle = value.lower()
        return lambda tx, p: needle in tx.narration.lower()
    if name == "tag":
        wanted = value.lower()
        return lambda tx, p: any(t.lower() == wanted for t in tx.tags)
    if name == "date":
        try:
            period = Period.parse(value)
        except (TallybookError, ValueError, OverflowError):
            _fail("invalid period '%s'" % value, start)
        return lambda tx, p: period.contains(tx.date)
