        if value not in ("*", "!"):
            _fail("invalid flag '%s': use * or !" % value, start)
        return lambda tx, p: tx.flag == value
    if name == "id":
        if not re.fullmatch(r"[0-9]+", value):
            _fail("invalid id '%s'" % value, start)
        wanted = int(value)
        return lambda tx, p: tx.id is not None and tx.id == wanted
    pattern = _account_pattern(value)
    if pattern is None:
        _fail("invalid account pattern '%s'" % value, start)
    if chart is not None and not any(_pattern_matches(pattern, a.path) for a in chart.accounts()):
        _fail("no account matches '%s'" % value, start)
    return lambda tx, p: _pattern_matches(pattern, p.account)


# -- the parser -------------------------------------------------------------------

def _read_quoted(text, i):
    """Read a quoted string whose opening quote is at index i.

    Returns (value, index after the closing quote); QueryError if it never closes
    or is followed by something other than a space, parenthesis or the end.
    """
    n = len(text)
    out = []
    j = i + 1
    while True:
        if j >= n:
            _fail("unterminated quote", i + 1)
        c = text[j]
        if c == '"':
            j += 1
            break
        if c == "\\" and j + 1 < n and text[j + 1] in '"\\':
            out.append(text[j + 1])
            j += 2
            continue
        out.append(c)
        j += 1
    if j < n and text[j] not in _STOP:
        _fail("unexpected text after a closing quote", j + 1)
    return "".join(out), j


def _skip(text, i, chars=_SPACE):
    n = len(text)
    while i < n and text[i] in chars:
        i += 1
    return i


def _run(text, i):
    n = len(text)
    j = i
    while j < n and text[j] not in _STOP:
        j += 1
    return j


def _lex(text, i, chart):
    """Read one token at index i (not blank). Returns (kind, payload, next index)."""
    c = text[i]
    start = i + 1
    if c == "(":
        return "(", None, i + 1
    if c == ")":
        return ")", None, i + 1
    if c == '"':
        value, j = _read_quoted(text, i)
        if value == "":
            _fail("empty quoted text", start)
        return "t", _contains_text(value), j
    end = _run(text, i)
    raw = text[i:end]
    low = raw.lower()
    if low in ("and", "or", "not"):
        return low, None, end
    colon = raw.find(":")
    if colon >= 0:
        name = raw[:colon].lower()
        if name not in _NAMES:
            _fail("unknown name '%s'" % raw[:colon], start)
        k = i + colon + 1
        if k < len(text) and text[k] == '"':
            value, j = _read_quoted(text, k)
            if value == "":
                _fail("empty quoted value", start)
        else:
            j = _run(text, k)
            value = text[k:j]
            if value == "":
                _fail("missing value for '%s'" % raw[:colon], start)
        return "t", _named_term(name, value, chart, start), j
    m = _LETTERS.match(text, i)
    if m is not None:
        name = m.group().lower()
        k = _skip(text, m.end(), " \t")
        op = next((o for o in _OPS if text.startswith(o, k)), None)
        if op is not None and name in ("amount", "date"):
            v0 = _skip(text, k + len(op), " \t")
            j = _run(text, v0)
            value = text[v0:j]
            if value == "":
                _fail("missing value after '%s%s'" % (name, op), start)
            if name == "date":
                try:
                    literal = parse_date(value)
                except (TallybookError, ValueError):
                    _fail("invalid date '%s'" % value, start)
            else:
                literal = parse_number(value)
                if literal is None:
                    _fail("invalid amount '%s'" % value, start)
            return "t", _compare_term(literal, op, name), j
        if op is not None and k == m.end():
            _fail("unknown name '%s'" % m.group(), start)
    if raw == "":
        _fail("unexpected character", start)
    return "t", _contains_text(raw), end


def parse_query(text, chart=None):
    if not isinstance(text, str):
        _fail("a query must be text", 1)
    n = len(text)
    program = []
    ops = []  # entries (kind, position)
    expect_term = True
    last_open = None
    i = 0
    prec = {"or": 1, "and": 2, "not": 3}

    def flush(minimum):
        while ops and ops[-1][0] != "(" and prec[ops[-1][0]] >= minimum:
            program.append((ops.pop()[0], None))

    while True:
        i = _skip(text, i)
        if i >= n:
            kind, payload, pos, nxt = "end", None, n + 1, i
        else:
            kind, payload, nxt = _lex(text, i, chart)
            pos = i + 1
        if expect_term:
            if kind == "not":
                ops.append(("not", pos))
            elif kind == "(":
                ops.append(("(", pos))
            elif kind == "t":
                program.append(("t", payload))
                expect_term = False
            else:
                _fail("expected a search term", pos)
        else:
            if kind in ("and", "or"):
                flush(prec[kind])
                ops.append((kind, pos))
                expect_term = True
            elif kind == ")":
                flush(1)
                if not ops:
                    _fail("unmatched ')'", pos)
                ops.pop()
            elif kind == "end":
                flush(1)
                if ops:
                    _fail("unclosed '('", ops[-1][1])
                break
            else:
                # an implicit "and"; the token is read again as the start of a term
                flush(prec["and"])
                ops.append(("and", pos))
                expect_term = True
                continue
        i = nxt
    return Query(text, program)

