"""Rules: sort bank lines into accounts, first match wins."""
import re

from tallybook.accounts import valid_path
from tallybook.dates import parse_date
from tallybook.errors import ParseError, TallybookError
from tallybook.model import Posting, Transaction
from tallybook.query import compare_amount, parse_number

_BLANKS = " \t"
_TAG = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_OPCHARS = '<>=!~"'
_TEXT_OPS = ("=", "!=", "~", "!~")
_NUM_OPS = ("<", "<=", ">", ">=", "=", "!=")
_FIELDS = ("payee", "narration", "amount", "date")
_ACTIONS = ("account", "tag", "narration", "payee", "flag")
_ALL_OPS = ("!~", "!=", "<=", ">=", "<", ">", "=", "~")


class RulesError(ParseError):
    def __init__(self, message="", line=None, detail=None):
        ParseError.__init__(self, message, detail)
        self.line = line


class _Bad(Exception):
    pass


_COMPARE = {
    "<": lambda a, b: a < b,
    "<=": lambda a, b: a <= b,
    ">": lambda a, b: a > b,
    ">=": lambda a, b: a >= b,
    "=": lambda a, b: a == b,
    "!=": lambda a, b: a != b,
}


class _Cond:
    """One condition: ``field op value`` (value already converted)."""

    def __init__(self, field, op, value):
        self.field = field
        self.op = op
        self.value = value

    def holds(self, fields):
        field, op, value = self.field, self.op, self.value
        if field == "amount":
            return compare_amount(fields.get("amount"), value, op)
        if field == "date":
            got = fields.get("date")
            if not hasattr(got, "year"):
                return False
            return _COMPARE[op](got, value)
        got = fields.get(field)
        if not isinstance(got, str):
            got = ""
        if op == "=":
            return got.lower() == value.lower()
        if op == "!=":
            return got.lower() != value.lower()
        found = value.search(got) is not None
        return found if op == "~" else not found


class Rule:
    def __init__(self, line, conditions, account=None, tags=(), narration=None, payee=None, flag=None):
        self.line = line
        self.conditions = tuple(conditions)  # empty means "any"
        self.account = account
        self.tags = tuple(tags)
        self.narration = narration
        self.payee = payee
        self.flag = flag

    def __repr__(self):
        return "Rule(line=%d)" % self.line

    def holds(self, fields):
        return all(c.holds(fields) for c in self.conditions)

    def effect(self):
        out = {}
        if self.account is not None:
            out["account"] = self.account
        if self.tags:
            out["tags"] = list(self.tags)
        if self.narration is not None:
            out["narration"] = self.narration
        if self.payee is not None:
            out["payee"] = self.payee
        if self.flag is not None:
            out["flag"] = self.flag
        return out


class RuleSet:
    def __init__(self, rules=()):
        self._rules = list(rules)

    def __len__(self):
        return len(self._rules)

    def __iter__(self):
        return iter(list(self._rules))

    def match(self, fields):
        for rule in self._rules:
            if rule.holds(fields):
                return rule
        return None

    def apply(self, fields):
        rule = self.match(fields)
        return None if rule is None else rule.effect()

    def categorize(self, tx):
        postings = list(tx.postings)
        fields = {
            "payee": tx.payee,
            "narration": tx.narration,
            "date": tx.date,
            "amount": postings[0].amount if postings else None,
        }
        effect = self.apply(fields)
        if effect is None:
            return tx
        if "account" in effect and len(postings) == 2:
            second = postings[1]
            postings[1] = Posting(effect["account"], second.amount, second.note)
        tags = tuple(sorted(set(tx.tags) | set(effect.get("tags", ()))))
        return Transaction(tx.date, effect.get("payee", tx.payee),
                           effect.get("narration", tx.narration), postings, tags,
                           effect.get("flag", tx.flag), tx.id)


# -- reading a rules file -------------------------------------------------------

class _Line:
    """A cursor over one rule line."""

    def __init__(self, text):
        self.text = text
        self.i = 0

    def skip(self):
        n = len(self.text)
        while self.i < n and self.text[self.i] in _BLANKS:
            self.i += 1

    def at_end(self):
        self.skip()
        return self.i >= len(self.text)

    def word(self, stop=""):
        """The next run of non-blank characters (not running into a character of ``stop``)."""
        self.skip()
        start = self.i
        n = len(self.text)
        while self.i < n and self.text[self.i] not in _BLANKS and self.text[self.i] not in stop:
            self.i += 1
        return self.text[start:self.i]

    def operator(self):
        self.skip()
        for op in _ALL_OPS:
            if self.text.startswith(op, self.i):
                self.i += len(op)
                return op
        return None

    def string(self):
        """A quoted string: ``\\"`` is a quote, any other backslash pair is kept as written."""
        self.skip()
        text, n = self.text, len(self.text)
        if self.i >= n or text[self.i] != '"':
            raise _Bad("expected a quoted text")
        out = []
        j = self.i + 1
        while True:
            if j >= n:
                raise _Bad("missing closing quote")
            c = text[j]
            if c == '"':
                j += 1
                break
            if c == "\\":
                if j + 1 >= n:
                    raise _Bad("missing closing quote")
                nxt = text[j + 1]
                out.append('"' if nxt == '"' else c + nxt)
                j += 2
                continue
            out.append(c)
            j += 1
        if j < n and text[j] not in _BLANKS:
            raise _Bad("text right after a closing quote")
        self.i = j
        return "".join(out)


def _regex(source):
    try:
        return re.compile(source, re.IGNORECASE)
    except (re.error, RecursionError, OverflowError, ValueError, MemoryError) as err:
        raise _Bad("invalid regular expression: %s" % (err,))


def _condition(cur):
    field = cur.word(_OPCHARS)
    if field == "any":
        raise _Bad("'any' cannot be combined with other conditions")
    if field not in _FIELDS:
        raise _Bad("unknown field '%s'" % field)
    op = cur.operator()
    if op is None:
        raise _Bad("missing or unknown operator after '%s'" % field)
    if field in ("payee", "narration"):
        if op not in _TEXT_OPS:
            raise _Bad("operator %s does not fit %s" % (op, field))
        text = cur.string()
        return _Cond(field, op, _regex(text) if op in ("~", "!~") else text)
    if op not in _NUM_OPS:
        raise _Bad("operator %s does not fit %s" % (op, field))
    value = cur.word()
    if value == "":
        raise _Bad("missing value after %s %s" % (field, op))
    if field == "date":
        try:
            return _Cond(field, op, parse_date(value))
        except TallybookError:
            raise _Bad("invalid date '%s'" % value)
    number = parse_number(value)
    if number is None:
        raise _Bad("invalid amount '%s'" % value)
    return _Cond(field, op, number)


def _parse_rule(number, text):
    cur = _Line(text)
    if cur.word() != "when":
        raise _Bad("a rule starts with 'when'")
    conditions = []
    if cur.at_end():
        raise _Bad("nothing after 'when'")
    save = cur.i
    if cur.word() == "any":
        if cur.word() != "then":
            raise _Bad("'any' cannot be combined with other conditions")
    else:
        cur.i = save
        while True:
            conditions.append(_condition(cur))
            word = cur.word()
            if word == "then":
                break
            if word != "and":
                raise _Bad("expected 'and' or 'then'" if word else "missing 'then'")
    seen = {}
    tags = []
    if cur.at_end():
        raise _Bad("nothing after 'then'")
    while not cur.at_end():
        name = cur.word()
        if name not in _ACTIONS:
            raise _Bad("unknown action '%s'" % name)
        if name != "tag" and name in seen:
            raise _Bad("'%s' given twice" % name)
        if cur.at_end():
            raise _Bad("'%s' needs a value" % name)
        if name in ("narration", "payee"):
            value = cur.string()
            if name == "payee" and not value.strip(_BLANKS):
                raise _Bad("the payee may not be empty")
        else:
            value = cur.word()
            if name == "account" and not valid_path(value):
                raise _Bad("invalid account path '%s'" % value)
            if name == "flag" and value not in ("*", "!"):
                raise _Bad("invalid flag '%s': use * or !" % value)
            if name == "tag":
                if not _TAG.fullmatch(value):
                    raise _Bad("invalid tag '%s'" % value)
                value = value.lower()
                if value not in tags:
                    tags.append(value)
        seen[name] = value
    return Rule(number, conditions, seen.get("account"), tags, seen.get("narration"),
                seen.get("payee"), seen.get("flag"))


def parse_rules(text):
    if not isinstance(text, str):
        raise RulesError("rules text must be a string")
    if text.startswith("﻿"):
        text = text[1:]
    rules = []
    for number, raw in enumerate(text.split("\n"), 1):
        line = raw[:-1] if raw.endswith("\r") else raw
        stripped = line.strip(_BLANKS)
        if stripped == "" or stripped[0] == "#":
            continue
        try:
            rules.append(_parse_rule(number, line))
        except _Bad as err:
            raise RulesError("line %d: %s" % (number, err), number)
    return RuleSet(rules)

