        stripped = line.strip(_BLANKS)
        if stripped == "" or stripped[0] == "#":
            continue
        try:
            name, eq, value = line.partition("=")
            if not eq:
                raise _Bad("expected 'setting = value'")
            name = name.strip(_BLANKS)
            value = value.strip(_BLANKS)
            if name not in _SETTINGS:
                raise _Bad("unknown setting '%s'" % name)
            if name in values:
                raise _Bad("setting '%s' given twice" % name)
            if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
                value = value[1:-1]
            values[name] = _setting(name, value)
            lines[name] = number
        except _Bad as err:
            raise CsvImportError("line %d: %s" % (number, err), number)
    if values.get("has_header", True) is False:
        for name in _COLUMNS:
            if name in values and not values[name].startswith("#"):
                raise CsvImportError(
                    "line %d: column '%s' needs has_header = yes (or write #N)" % (lines[name], values[name]),
                    lines[name])
    for name in ("date_column", "payee_column", "currency", "account"):
        if name not in values:
            raise CsvImportError("missing required setting '%s'" % name)
    single = "amount_column" in values
    split = [n for n in ("debit_column", "credit_column") if n in values]
    if single and split:
        raise CsvImportError("amount_column cannot be combined with debit_column/credit_column")
    if len(split) == 1:
        raise CsvImportError("debit_column and credit_column must be given together")
    if not single and not split:
        raise CsvImportError("missing amount_column (or debit_column and credit_column)")
    profile = ImportProfile(**values)
    if profile.thousands_separator and profile.thousands_separator == profile.decimal_separator:
        raise CsvImportError("decimal_separator and thousands_separator must differ")
    return profile


# -- reading the file ------------------------------------------------------------------

def _skip_lines(text, count):
    """Drop ``count`` lines (ended by \\n, \\r\\n or \\r); returns (rest, lines dropped)."""
    i = 0
    n = len(text)
    dropped = 0
    while dropped < count and i < n:
        j = i
        while j < n and text[j] not in "\r\n":
            j += 1
        if j < n:
            j += 2 if text.startswith("\r\n", j) else 1
        dropped += 1
        i = j
    return text[i:], dropped


def _records(text, delimiter, first_line):
    """Yield (line number, cells, closed) for each record; ``closed`` is False for an
    unterminated quote."""
    n = len(text)
    i = 0
    line = first_line
    while i < n:
        start_line = line
        cells = []
        cell = []
        closed = True
        while True:
            if i >= n:
                cells.append("".join(cell))
                break
            c = text[i]
            if c == '"' and not cell:
                i += 1
                while True:
                    if i >= n:
                        closed = False
                        break
                    c = text[i]
                    if c == '"':
                        if text.startswith('""', i):
                            cell.append('"')
                            i += 2
                            continue
                        i += 1
                        break
                    if c == "\n":
                        line += 1
                    cell.append(c)
                    i += 1
                # text after a closing quote up to the delimiter is kept literally
                while i < n and text[i] != delimiter and text[i] != "\n" and not text.startswith("\r\n", i):
                    cell.append(text[i])
                    i += 1
                continue
            if c == delimiter:
                cells.append("".join(cell))
                cell = []
                i += 1
                continue
            if c == "\n" or text.startswith("\r\n", i):
                cells.append("".join(cell))
                i += 1 if c == "\n" else 2
                line += 1
                break
            cell.append(c)
            i += 1
        yield start_line, cells, closed


def _is_blank(cells):
    return all(c.strip() == "" for c in cells)


def _find_column(spec, header):
    """Index of a column, or None when it is not in the header."""
    if spec.startswith("#"):
        return int(spec[1:]) - 1
    wanted = spec.strip().lower()
    for k, name in enumerate(header):
        if name.strip().lower() == wanted:
            return k
    return None


def _clean(cell):
    return " ".join(cell.split())


# -- amounts ----------------------------------------------------------------------------

def _amount_regex(profile):
    dec = re.escape(profile.decimal_separator)
    if profile.thousands_separator:
        th = re.escape(profile.thousands_separator)
        whole = "(?:[0-9]{1,3}(?:%s[0-9]{3})+|[0-9]+)" % th
    else:
        whole = "[0-9]+"
    return re.compile("(%s)(?:%s([0-9]+))?" % (whole, dec))


def _read_amount(cell, profile, rx):
    """The minor units written in a cell (never None; raises _Bad)."""
    text = cell.strip()
    if text == "":
        raise _Bad("empty amount")
    negative = False
    if text.startswith("(") and text.endswith(")") and len(text) > 2:
        negative = True
        body = text[1:-1]
    else:
        body = text
        if body[0] in "+-":
            negative = body[0] == "-"
            body = body[1:]
    m = rx.fullmatch(body)
    if m is None:
        raise _Bad("bad amount '%s'" % text)
    whole = m.group(1)
    if profile.thousands_separator:
        whole = whole.replace(profile.thousands_separator, "")
    frac = m.group(2)
    normal = whole + ("." + frac if frac is not None else "")
    try:
        minor = parse_amount(normal, profile.currency)
    except TallybookError:
        raise _Bad("bad amount '%s': too many decimal places for %s" % (text, profile.currency))
    except (ValueError, OverflowError):
        raise _Bad("bad amount '%s'" % text)
    return -minor if negative else minor


def _row_amount(cells, cols, profile, rx):
    if cols["amount"] is not None:
        minor = _read_amount(cells[cols["amount"]], profile, rx)
    else:
        debit, credit = cells[cols["debit"]].strip(), cells[cols["credit"]].strip()
        if debit and credit:
            raise _Bad("both debit and credit are filled")
        if not debit and not credit:
            raise _Bad("neither debit nor credit is filled")
        minor = (_read_amount(credit, profile, rx) if credit
                 else -_read_amount(debit, profile, rx))
    if profile.negate:
        minor = -minor
    if minor == 0:
        raise _Bad("the amount is zero")
    return minor


# -- importing -----------------------------------------------------------------------------

def _needed(cells, index, spec):
    if index is None or index >= len(cells):
        raise _Bad("row is too short: no column %s" % spec)
    return cells[index]


def _build_row(cells, cols, specs, profile, rx, rules):
    when = _read_date(_needed(cells, cols["date"], specs["date"]).strip(), profile.date_format)
    payee = _clean(_needed(cells, cols["payee"], specs["payee"]))
    if payee == "":
        raise _Bad("empty payee")
    narration = ""
    if cols["narration"] is not None and cols["narration"] < len(cells):
        narration = _clean(cells[cols["narration"]])
    for key in ("amount", "debit", "credit"):
        if cols[key] is not None:
            _needed(cells, cols[key], specs[key])
    minor = _row_amount(cells, cols, profile, rx)
    amount = Money(minor, profile.currency)
    account = None
    flag = profile.flag
    tags = set(profile.tags)
    if rules is not None:
        got = rules.apply({"payee": payee, "narration": narration, "date": when, "amount": amount})
        if got is not None:
            account = got.get("account")
            payee = got.get("payee", payee)
            narration = got.get("narration", narration)
            flag = got.get("flag", flag)
            tags.update(got.get("tags", ()))
    if account is None:
        account = profile.default_account
    if account is None:
        raise _Bad("no account for the other side: no rule matched and no default_account")
    postings = [Posting(profile.account, amount), Posting(account, -amount)]
    return Transaction(when, payee, narration, postings, tuple(sorted(tags)), flag, None)


def _key(tx, account):
    for p in tx.postings:
        if p.account == account and p.amount is not None:
            return (tx.date, p.amount.minor, p.amount.currency, tx.payee)
    return None


def import_csv(text, profile, rules=None, existing=()):
    if not isinstance(text, str):
        raise CsvImportError("csv text must be a string")
    if isinstance(profile, str):
        profile = parse_profile(profile)
    if isinstance(rules, str):
        rules = parse_rules(rules)
    if rules is not None and not isinstance(rules, RuleSet):
        rules = RuleSet(list(rules))
    if text.startswith("\ufeff"):
        text = text[1:]
    text, dropped = _skip_lines(text, profile.skip_rows)
    records = _records(text, profile.delimiter, dropped + 1)

    specs = {"date": profile.date_column, "payee": profile.payee_column,
             "narration": profile.narration_column, "amount": profile.amount_column,
             "debit": profile.debit_column, "credit": profile.credit_column}
    header = []
    if profile.has_header:
        for _, cells, _ in records:
            if not _is_blank(cells):
                header = cells
                break
        else:
            raise CsvImportError("the file has no header row")
    cols = {}
    for key, spec in specs.items():
        if spec is None:
            cols[key] = None
            continue
        index = _find_column(spec, header)
        if index is None:
            raise CsvImportError("column '%s' is not in the header" % spec)
        cols[key] = index

    counts = {}
    for tx in existing:
        key = _key(tx, profile.account)
        if key is not None:
            counts[key] = counts.get(key, 0) + 1

    rx = _amount_regex(profile)
    result = ImportResult()
    seen = {}
    for number, cells, closed in records:
        if _is_blank(cells):
            continue
        try:
            if not closed:
                raise _Bad("unterminated quoted field")
            tx = _build_row(cells, cols, specs, profile, rx, rules)
        except _Bad as err:
            result.errors.append((number, str(err)))
            continue
        key = _key(tx, profile.account)
        seen[key] = seen.get(key, 0) + 1
        if seen[key] <= counts.get(key, 0):
            result.duplicates.append(tx)
        else:
            result.transactions.append(tx)
    return result

